import os
import re
import pytesseract
from PIL import Image
from openpyxl import Workbook

def extract_date(text):
    patterns = [
        r'(\d{2})[/-](\d{2})[/-](\d{4})',
        r'(\d{4})[/-](\d{2})[/-](\d{2})',
        r'(\d{2})\.(\d{2})\.(\d{4})',
        r'(\d{4})\.(\d{2})\.(\d{2})',
        r'(\d{2})[/-](\d{2})[/-](\d{2})\b',
        r'(\d{2})\.(\d{2})\.(\d{2})\b'
    ]
    for pattern in patterns:
        matches = re.findall(pattern, text)
        for match in matches:
            try:
                if len(match[0]) == 4: y, m, d = match; y = int(y)
                elif len(match[2]) == 4: d, m, y = match; y = int(y)
                else: d, m, y = match; y = int(y) + 2000
                m, d = int(m), int(d)
                if 1 <= m <= 12 and 1 <= d <= 31: return f"{y:04d}-{m:02d}-{d:02d}"
            except: continue
    return None

def clean_amount_str(s):
    s = s.replace('S', '5').replace('s', '5').replace('B', '8')
    s = s.replace('i', '1').replace('I', '1').replace('l', '1')
    s = s.replace('O', '0').replace('o', '0').replace('U', '0').replace('D', '0')
    s = re.sub(r'[^0-9.,]', '', s)
    return s

def extract_total_amount(lines):
    keywords_p1 = [r'GR[A4]ND\s*T[O0]TAL']
    keywords_p2 = [r'T[O0]TAL\s*RM', r'T[O0]TAL:\s*RM']
    keywords_p3 = [r'T[O0]TAL\s*AM[O0]UNT']
    keywords_p4 = [r'T[O0]TAL', r'AM[O0]UNT', r'T[O0]TAL\s*DUE', r'AM[O0]UNT\s*DUE', r'BAL[A4]NCE\s*DUE', r'[NH]E[T7][T7]?\s*T[O0]TAL']
    exclusion_keywords = [
        r'SUB[- ]*[TL0OI1]{1,2}[O0]TAL', r'SUB\s*[- ]*[TL0OI1]{1,2}[O0]TAL', 
        r'T[A4]X', r'GS[T7]', r'SS[T7]', r'D[I1]SC[O0]UNT', r'CH[A4]NGE', 
        r'C[A4]SH\s*TENDERED', r'C[A4]SH\b', r'V[I1]S[A4]', r'M[A4]STER', r'DEB[I1]T'
    ]
    priority_groups = [keywords_p1, keywords_p2, keywords_p3, keywords_p4]
    flexible_amount_pattern = r'([\dISBlOouUD]{1,3}(?:[,\s][\dISBlOouUD]{3})*[.,\s]+[\dISBlOouUD]{2})\b'

    for group in priority_groups:
        for i, line in enumerate(lines):
            upper_line = line.upper()
            for kw in group:
                if re.search(kw, upper_line):
                    is_excluded = False
                    for ex in exclusion_keywords:
                        if re.search(ex, upper_line):
                            if (ex == 'GS[T7]' or ex == 'SS[T7]') and 'INCL' in upper_line: continue
                            is_excluded = True; break
                    if is_excluded: continue

                    kw_match = re.search(kw, upper_line)
                    after_kw = line[kw_match.end():]
                    amounts = re.findall(flexible_amount_pattern, after_kw)
                    if not amounts: amounts = re.findall(flexible_amount_pattern, line)

                    if amounts:
                        cleaned = clean_amount_str(amounts[-1])
                        if cleaned:
                            if '.' in cleaned: res = cleaned.replace(',', '')
                            elif len(cleaned) > 2: res = cleaned[:-2] + '.' + cleaned[-2:]
                            else: res = None
                            if res: return res

                    if i + 1 < len(lines):
                        next_line = lines[i+1]
                        if not any(re.search(ex, next_line.upper()) for ex in exclusion_keywords):
                            next_amounts = re.findall(flexible_amount_pattern, next_line)
                            if next_amounts:
                                cleaned = clean_amount_str(next_amounts[-1])
                                if '.' in cleaned: res = cleaned.replace(',', '')
                                elif len(cleaned) > 2: res = cleaned[:-2] + '.' + cleaned[-2:]
                                else: res = None
                                if res: return res
    return None

def process_images(img_dir):
    results = []
    filenames = sorted([f for f in os.listdir(img_dir) if f.endswith(('.jpg', '.jpeg', '.png'))])
    for filename in filenames:
        img_path = os.path.join(img_dir, filename)
        try:
            img = Image.open(img_path).convert('L')
            w, h = img.size
            img = img.resize((w*2, h*2), Image.Resampling.LANCZOS)
            text = pytesseract.image_to_string(img, config='--psm 6')
            date = extract_date(text)
            if not date: date = extract_date(pytesseract.image_to_string(img))

            total_amount = extract_total_amount(text.split('\n'))
            if not total_amount: total_amount = extract_total_amount(pytesseract.image_to_string(img).split('\n'))

            if total_amount:
                try: total_amount = "{:.2f}".format(float(total_amount))
                except: total_amount = None
            results.append({'filename': filename, 'date': date, 'total_amount': total_amount})
        except:
            results.append({'filename': filename, 'date': None, 'total_amount': None})
    return results

def save_to_excel(results, output_path):
    wb = Workbook()
    ws = wb.active
    ws.title = "results"
    ws.append(['filename', 'date', 'total_amount'])
    for res in results: ws.append([res['filename'], res['date'], res['total_amount']])
    wb.save(output_path)

if __name__ == "__main__":
    data = process_images("/app/workspace/dataset/img")
    save_to_excel(data, "/app/workspace/stat_ocr.xlsx")

